import { Flow, wfa, trigger } from '@servicenow/sdk/automation'

// Flow that defines a weekly scheduled trigger on a specific day and time.

Flow(
    {
        $id: Now.ID['flow_trigger_scheduled_weekly'],
        name: 'Flow - Trigger Scheduled Weekly',
        description: 'Flow used by tests to validate weekly scheduled trigger configuration.',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.scheduled.weekly,
        { $id: Now.ID['trigger_scheduled_weekly'], annotation: 'Weekly scheduled trigger on Monday at 08:30:00' },
        {
            day_of_week: 1,
            time: Time({ hours: 8, minutes: 30, seconds: 0 }),
        }
    ),
    () => {
        // Empty body; this test focuses on scheduled trigger configuration only
    }
)
